/**
 * Type definitions for fluent Try-Catch API
 */
/**
 * Function type for the body of the try and catch blocks.
 */
type TryCatchBodyFunction = () => void;
/**
 * Configuration for the TryCatch block.
 */
export interface TryCatchConfig {
    try: TryCatchBodyFunction;
    catch: TryCatchBodyFunction;
}
/**
 * Parameters for the TryCatch block.
 */
export type TryCatchParams = Now.Internal.WithID<{
    annotation?: string;
}>;
/**
 * Creates a try-catch block in Flow Logic.
 * @param params An object containing a unique identifier (`$id`) and an optional `annotation`.
 * @param config An object containing the `try` and `catch` functions.
 */
export declare function TryCatch(params: TryCatchParams, config: TryCatchConfig): {
    type: 'trycatch';
};
export {};
/**
 * Usage example:
 * ```typescript
 * TryCatch(Now.ID, {
 *    try: () => {
 *      // Code that might throw an error
 *    },
 *    catch: () => {
 *      // Code to handle the error
 *    }
 * });
 * ```
 */
